validateToolRegistry(TOOL_DEFINITIONS);

let registry: ToolRegistry | null = null;
let publicTools: ToolDefinition[] | null = null;

export function getPublicTools(): ToolDefinition[] {
  if (!publicTools) {
    publicTools = TOOL_DEFINITIONS.filter((tool) => tool.visibility === "public");
  }
  return publicTools;
}

export function getToolRegistry(): ToolRegistry {
  if (registry) return registry;
  registry = new InMemoryToolRegistry(TOOL_DEFINITIONS);
  return registry;
}
